              >
                <span className="material-symbols-outlined text-[16px]">mail</span>
                E-mail
              </button>
            </div>

            <form onSubmit={handleStartForgot} className="space-y-3.5">
              <div>
                <label className="block text-xs font-semibold text-on-surface mb-1">
                  {forgotIdentifierType === 'email' ? 'Endereço de E-mail' : 'Número de Telemóvel (+244)'}
                </label>
                <div className="relative">
                  <span className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none text-on-surface-variant">
                    <span className="material-symbols-outlined text-[18px]">
                      {forgotIdentifierType === 'email' ? 'mail' : 'phone_android'}
                    </span>
                  </span>
                  <input
                    type={forgotIdentifierType === 'email' ? 'email' : 'tel'}
                    placeholder={forgotIdentifierType === 'email' ? 'ex: joao@email.com' : 'ex: 923 123 456'}
                    value={forgotIdentifier}
                    onChange={(e) => setForgotIdentifier(e.target.value)}
                    className="w-full bg-surface-container-low border border-surface-border rounded-xl pl-9 pr-3 py-3 text-xs outline-none focus:border-primary focus:ring-2 focus:ring-primary/20 font-medium"
                    required
                  />
                </div>
              </div>

              <button
                type="submit"
                className="w-full py-3.5 bg-primary text-white font-display font-bold text-xs rounded-xl shadow-md hover:bg-primary/95 transition-all flex items-center justify-center gap-1.5 cursor-pointer mt-2"
              >
                <span>Enviar Código de Recuperação</span>
                <span className="material-symbols-outlined text-[16px]">send</span>
              </button>
            </form>
          </div>
        )}

        {/* ========================================================================= */}
        {/* 6. FORGOT PASSWORD STEP 2: Verify OTP                                     */}
        {/* ========================================================================= */}
        {mode === 'forgot_otp' && (
          <div className="space-y-5">
            <div>
              <button
                type="button"
                onClick={() => setMode('forgot_input')}
                className="text-xs text-on-surface-variant hover:text-primary font-bold flex items-center gap-1 mb-2"
              >
                <span className="material-symbols-outlined text-[16px]">arrow_back</span>
                Alterar {activeSession?.type === 'email' ? 'e-mail' : 'número'}
              </button>
              <h3 className="font-display text-xl font-bold text-on-surface">
                Código de Recuperação
              </h3>
              <p className="text-xs text-on-surface-variant mt-0.5">
                Introduza o código de 6 dígitos que enviámos para{' '}
                <strong className="text-on-surface">{activeSession?.target}</strong>.
              </p>
            </div>

            <form onSubmit={handleVerifyForgotOtp} className="space-y-4">
              {/* 6 Digits Boxes */}
              <div className="flex justify-between gap-2">
                {otpDigits.map((digit, idx) => (
                  <input
                    key={idx}
                    id={`otp-input-${idx}`}
                    type="text"
                    maxLength={1}
                    value={digit}
                    onChange={(e) => handleOtpDigitChange(idx, e.target.value)}
                    onKeyDown={(e) => handleOtpKeyDown(idx, e)}
                    className="w-11 h-13 text-center bg-surface-container-low border border-surface-border rounded-xl text-lg font-bold font-mono outline-none focus:border-primary focus:ring-2 focus:ring-primary/20 text-on-surface"
                  />
                ))}
              </div>

              {/* Timer Countdown & Resend Option */}
              <div className="flex items-center justify-between text-xs bg-surface-container p-3 rounded-xl border border-surface-border">
                <div className="flex items-center gap-1.5">
                  <span className="material-symbols-outlined text-[16px] text-primary">
                    timer
                  </span>
                  <span className="text-on-surface-variant">
                    {timeLeft > 0 ? (
                      <>Expira em: <strong className="text-primary font-mono">{formatTimer(timeLeft)}</strong></>
                    ) : (
                      <span className="text-error font-bold">Código expirado</span>
                    )}
                  </span>
                </div>

                <button
                  type="button"
                  onClick={handleResendOtp}
                  disabled={resendCooldown > 0}
                  className="font-bold text-primary hover:underline disabled:opacity-50 disabled:no-underline flex items-center gap-1"
                >
                  <span className="material-symbols-outlined text-[14px]">refresh</span>
                  {resendCooldown > 0 ? `Reenviar (${resendCooldown}s)` : 'Reenviar código'}
                </button>
              </div>

              <button
                type="submit"
                className="w-full py-3.5 bg-primary text-white font-display font-bold text-xs rounded-xl shadow-md hover:bg-primary/95 transition-all flex items-center justify-center gap-1.5 cursor-pointer"
              >
                <span>Validar Código</span>
                <span className="material-symbols-outlined text-[16px]">check_circle</span>
              </button>
            </form>
          </div>
        )}

        {/* ========================================================================= */}
        {/* 7. FORGOT PASSWORD STEP 3: Set New Password                               */}
        {/* ========================================================================= */}
        {mode === 'forgot_password' && (
          <div className="space-y-5">
            <div>
              <div className="w-11 h-11 rounded-2xl bg-primary/10 text-primary flex items-center justify-center mb-3">
                <span className="material-symbols-outlined text-[24px]">lock_reset</span>
              </div>
              <h3 className="font-display text-xl font-bold text-on-surface">
                Definir Nova Palavra-passe
              </h3>
              <p className="text-xs text-on-surface-variant mt-0.5">
                Crie uma nova palavra-passe segura para a sua conta.
              </p>
            </div>

            <form onSubmit={handleFinishForgot} className="space-y-3.5">
              <div>
                <label className="block text-xs font-semibold text-on-surface mb-1">
                  Nova Palavra-passe <span className="text-error">*</span>
                </label>
                <div className="relative">
                  <span className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none text-on-surface-variant">
                    <span className="material-symbols-outlined text-[18px]">lock</span>
                  </span>
                  <input
                    type={showPassword ? 'text' : 'password'}
                    placeholder="••••••••"
                    value={newPassword}
                    onChange={(e) => setNewPassword(e.target.value)}
                    className="w-full bg-surface-container-low border border-surface-border rounded-xl pl-9 pr-10 py-3 text-xs outline-none focus:border-primary focus:ring-2 focus:ring-primary/20 font-mono"
                    required
                  />
                  <button
                    type="button"
                    onClick={() => setShowPassword(!showPassword)}
                    className="absolute inset-y-0 right-0 pr-3 flex items-center text-on-surface-variant hover:text-on-surface"
                  >
                    <span className="material-symbols-outlined text-[18px]">
                      {showPassword ? 'visibility_off' : 'visibility'}
                    </span>
                  </button>
                </div>
              </div>

              <div>
                <label className="block text-xs font-semibold text-on-surface mb-1">
                  Confirmar Nova Palavra-passe <span className="text-error">*</span>
                </label>
                <div className="relative">
                  <span className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none text-on-surface-variant">
                    <span className="material-symbols-outlined text-[18px]">lock_reset</span>
                  </span>
                  <input
                    type={showPassword ? 'text' : 'password'}
                    placeholder="••••••••"
                    value={confirmNewPassword}
                    onChange={(e) => setConfirmNewPassword(e.target.value)}
                    className="w-full bg-surface-container-low border border-surface-border rounded-xl pl-9 pr-3 py-3 text-xs outline-none focus:border-primary focus:ring-2 focus:ring-primary/20 font-mono"
                    required
                  />
                </div>
              </div>

              <button
                type="submit"
                className="w-full py-3.5 bg-primary text-white font-display font-bold text-xs rounded-xl shadow-md hover:bg-primary/95 transition-all flex items-center justify-center gap-1.5 cursor-pointer mt-2"
              >
                <span>Guardar Nova Palavra-passe & Entrar</span>
                <span className="material-symbols-outlined text-[16px]">save</span>
              </button>
            </form>
          </div>
        )}

        {/* ========================================================================= */}
        {/* 8. PROFILE VIEW (Logged In)                                               */}
        {/* ========================================================================= */}
        {mode === 'profile' && currentUser && (
          <div className="space-y-5">
            <div className="flex items-center gap-3 pb-3 border-b border-surface-border">
              {currentUser.avatarUrl ? (
                <img
                  src={currentUser.avatarUrl}
                  alt={currentUser.name}
                  className="w-14 h-14 rounded-2xl object-cover border border-primary/20"
                />
              ) : (
                <div className="w-14 h-14 rounded-2xl bg-primary text-white font-display font-extrabold text-lg flex items-center justify-center">
                  {currentUser.initials}
                </div>
              )}
              <div>
                <h3 className="font-display text-base font-bold text-on-surface">
                  {currentUser.name}
                </h3>
                <p className="text-xs text-on-surface-variant font-mono">
                  {currentUser.phone || currentUser.email}
                </p>
                <span className="inline-block mt-1 text-[10px] bg-emerald-100 text-emerald-800 font-bold px-2 py-0.5 rounded-full">
                  Conta Ativa
                </span>
              </div>
            </div>

            <div className="space-y-2 text-xs">
              <div className="flex justify-between p-3 rounded-xl bg-surface-container-low border border-surface-border">
                <span className="text-on-surface-variant">E-mail:</span>
                <span className="font-medium text-on-surface">{currentUser.email || 'Não associado'}</span>
              </div>
              <div className="flex justify-between p-3 rounded-xl bg-surface-container-low border border-surface-border">
                <span className="text-on-surface-variant">Telemóvel (Angola):</span>
                <span className="font-medium text-on-surface font-mono">{currentUser.phone || 'Não associado'}</span>
              </div>
              <div className="flex justify-between p-3 rounded-xl bg-surface-container-low border border-surface-border">
                <span className="text-on-surface-variant">Membro desde:</span>
                <span className="font-medium text-on-surface">{currentUser.registrationDate}</span>
              </div>
              <div className="flex justify-between p-3 rounded-xl bg-surface-container-low border border-surface-border">
                <span className="text-on-surface-variant">CVs Criados:</span>
                <span className="font-bold text-primary">{currentUser.cvsGenerated} currículos</span>
              </div>
            </div>

            <div className="pt-2 flex flex-col gap-2">
              {(currentUser.role === 'admin' || currentUser.email?.toLowerCase().trim() === 'admin.prospekta@gmail.com') && onNavigateAdmin && (
                <button
                  type="button"
                  onClick={() => {
                    onClose();
                    onNavigateAdmin();
                  }}
                  className="w-full py-3 bg-primary text-white hover:bg-primary/95 font-bold text-xs rounded-xl transition-all flex items-center justify-center gap-1.5 cursor-pointer shadow-sm"
                >
                  <span className="material-symbols-outlined text-[18px]">admin_panel_settings</span>
                  <span>Aceder ao Painel Administrativo</span>
                </button>
              )}

              <button
                type="button"
                onClick={() => {
                  setCurrentUser(null);
                  onToast('Sessão terminada.');
                  onClose();
                }}
                className="w-full py-3 bg-error/10 text-error hover:bg-error/20 font-bold text-xs rounded-xl transition-all flex items-center justify-center gap-1.5 cursor-pointer"
              >
                <span className="material-symbols-outlined text-[16px]">logout</span>
                Terminar Sessão
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { AI_SUMMARY_SUGGESTIONS } from '../../data/initialData';

export type AISuggestionMode = 'summary' | 'experience' | 'skills';

interface AISuggestionModalProps {
  mode?: AISuggestionMode;
  currentText: string;
  contextTitle?: string; // e.g. "Engenheiro de Software", "Contabilista"
  contextCompany?: string; // e.g. "Unitel", "Sonangol"
  onApply: (newText: string) => void;
  onApplySkills?: (skillsList: string[]) => void;
  onClose: () => void;
}

export const AISuggestionModal: React.FC<AISuggestionModalProps> = ({
  mode = 'summary',
  currentText,
  contextTitle = '',
  contextCompany = '',
  onApply,
  onApplySkills,
  onClose,
}) => {
  const [customPrompt, setCustomPrompt] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [generatedResult, setGeneratedResult] = useState<string | null>(null);
  const [suggestedSkills, setSuggestedSkills] = useState<string[]>([]);
  const [selectedSkills, setSelectedSkills] = useState<string[]>([]);

  // Preset Experience Suggestions for Angola Job Market
  const EXPERIENCE_SUGGESTIONS = [
    {
      role: 'Gestão, Contabilidade & Finanças',
      bullet: 'Liderança na reconciliação contabilística diária no software Primavera/PHC, preparação de declarações fiscais e apuramento rigoroso de impostos em conformidade com as diretrizes da AGT.',
    },
    {
      role: 'Engenharia, TI & Telecomunicações',
      bullet: 'Supervisão técnica de infraestrutura de redes, resolução rápida de incidentes operacionais de nível 2/3 e otimização de disponibilidade de sistemas corporativos.',
    },
    {
      role: 'Vendas, Comercial & Atendimento',
      bullet: 'Superação consistente de metas de vendas mensais em 15%, prospeção ativa de clientes corporativos e negociação de contratos estratégicos no mercado de Luanda.',
    },
    {
      role: 'Logística & Gestão de Armazém',
      bullet: 'Controlo rigoroso de inventário e expedição de mercadorias, redução de discrepâncias de stock em 20% e coordenação de equipa de motoristas e operadores.',
    },
    {
      role: 'Recursos Humanos & Administrativo',
      bullet: 'Gestão de processos de admissão, cálculo de folhas de salário, controlo de assiduidade e implementação de boas práticas de atendimento e organização documental.',
    },
  ];

  // Preset Skills by Category
  const SKILL_CATEGORIES = [
    {
      name: 'Sistemas & ERPs em Angola',
      skills: ['Primavera BSS v10', 'PHC Software', 'SAP ERP', 'Sage 50', 'Power BI'],
    },
    {
      name: 'Gestão & Finanças',
      skills: ['Legislação Fiscal AGT', 'Reconciliação Bancária', 'Fluxo de Caixa', 'Contabilidade Geral', 'Auditoria'],
    },
    {
      name: 'Tecnologia & Redes',
      skills: ['Administração Windows Server', 'Cisco CCNA / Redes', 'Suporte Técnico Helpdesk', 'Segurança da Informação', 'SQL / Bases de Dados'],
    },
    {
      name: 'Competências Interpessoais (Soft Skills)',
      skills: ['Liderança de Equipas', 'Comunicação Assertiva', 'Resolução de Problemas', 'Gestão de Tempo', 'Foco em Resultados'],
    },
  ];

  const handleEnhanceExperience = () => {
    setIsGenerating(true);
    setTimeout(() => {
      setIsGenerating(false);
      const roleText = contextTitle || 'função desempenhada';
      const compText = contextCompany ? ` na ${contextCompany}` : '';
      const base = currentText.trim() ? currentText : `Responsável pelas operações chave como ${roleText}${compText}`;

      const enhanced = `${base}. Atuação com elevado rigor técnico e foco em resultados mensuráveis, garantindo a otimização de processos internos, mitigação de falhas operacionais e cumprimento estrito de prazos e normas corporativas.`;
      setGeneratedResult(enhanced);
    }, 800);
  };

  const handleEnhanceSummary = () => {
    setIsGenerating(true);
    setTimeout(() => {
      setIsGenerating(false);
      const roleText = contextTitle || 'na sua área de especialidade';
      const enhanced = currentText.trim()
        ? `Profissional experiente e proativo com trajetória sólida: ${currentText}. Destaco-me pela capacidade de liderança, comunicação assertiva, rápida adaptabilidade e forte compromisso com o crescimento organizacional e excelência de serviço.`
        : `Profissional dinâmico e orientado para metas com sólida experiência em ${roleText}. Elevado conhecimento do mercado corporativo angolano, capacidade analítica apurada e dedicação à melhoria contínua de produtividade.`;
      setGeneratedResult(enhanced);
    }, 800);
  };

  const handleGenerateFromCustom = () => {
    if (!customPrompt.trim() && !currentText.trim()) return;
    setIsGenerating(true);
    setTimeout(() => {
      setIsGenerating(false);
      if (mode === 'skills') {
        const generated = [
          'Primavera BSS',
          'Gestão de Processos',
          'Excel Avançado',
          'Comunicação Corporativa',
          'Trabalho em Equipa',
          'Planeamento Estratégico',
        ];
        setSuggestedSkills(generated);
        setSelectedSkills(generated);
      } else {
        const text = `Atuação estratégica com foco em ${customPrompt || 'otimização de operações'}. Forte perfil resolutivo, rigor na execução de tarefas e contribuição direta para a eficiência e competitividade da organização.`;
        setGeneratedResult(text);
      }
    }, 800);
  };

  const toggleSkillSelection = (skill: string) => {
    if (selectedSkills.includes(skill)) {
      setSelectedSkills(selectedSkills.filter((s) => s !== skill));
    } else {
      setSelectedSkills([...selectedSkills, skill]);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-xs">
      <div className="bg-surface-container-lowest rounded-2xl max-w-xl w-full p-6 shadow-2xl border border-surface-border animate-in fade-in zoom-in-95 duration-200 flex flex-col max-h-[90vh]">
        {/* Header */}
        <div className="flex items-center justify-between border-b border-surface-border pb-4">
          <div className="flex items-center gap-2.5">
            <div className="w-9 h-9 rounded-xl bg-primary/10 flex items-center justify-center text-primary">
              <span className="material-symbols-outlined text-[20px]" style={{ fontVariationSettings: "'FILL' 1" }}>
                auto_awesome
              </span>
            </div>
            <div>
              <h3 className="font-display text-base font-bold text-on-surface">
                {mode === 'summary' && 'Assistente IA: Resumo Profissional'}
                {mode === 'experience' && 'Assistente IA: Descrição de Experiência'}
                {mode === 'skills' && 'Assistente IA: Sugestão de Competências'}
              </h3>
              <p className="text-xs text-on-surface-variant">
                Textos otimizados com linguagem corporativa e verbos de ação para o mercado de Angola.
              </p>
            </div>
          </div>
          <button
            onClick={onClose}
            className="text-on-surface-variant hover:text-on-surface p-1 rounded-lg hover:bg-surface-container-high transition-colors"
          >
            <span className="material-symbols-outlined">close</span>
          </button>
        </div>

        {/* Modal Body */}
        <div className="flex-1 overflow-y-auto py-4 space-y-4">
          {/* Quick 1-Click Action for current context */}
          <div className="p-3.5 bg-surface-container-low rounded-xl border border-surface-border/70 space-y-2">
            <div className="flex justify-between items-baseline">
              <span className="text-xs font-bold text-on-surface">
                {mode === 'experience' ? 'Otimizar Experiência Atual:' : 'Otimizar com Base no Seu Perfil:'}
              </span>
              {contextTitle && (
                <span className="text-[10px] bg-primary/10 text-primary font-semibold px-2 py-0.5 rounded-md">
                  {contextTitle} {contextCompany ? `@ ${contextCompany}` : ''}
                </span>
              )}
            </div>

            {currentText && (
              <p className="text-xs text-on-surface-variant italic line-clamp-2 bg-white/70 p-2 rounded-lg border border-surface-border/40">
                "{currentText}"
              </p>
            )}

            <button
              type="button"
              onClick={mode === 'experience' ? handleEnhanceExperience : handleEnhanceSummary}
              disabled={isGenerating}
              className="w-full py-2.5 bg-gradient-to-r from-primary to-emerald-600 hover:from-primary/95 hover:to-emerald-600/95 text-white rounded-xl text-xs font-bold transition-all shadow-xs flex items-center justify-center gap-1.5"
            >
              <span className="material-symbols-outlined text-[16px]">magic_button</span>
              {isGenerating ? 'A gerar texto profissional...' : 'Gerar Versão Otimizada com IA'}
            </button>
          </div>

          {/* Mode Specific: Experience Presets */}
          {mode === 'experience' && (
            <div>
              <label className="block text-xs font-bold text-on-surface mb-2">
                Frases de Realizações Prontas por Área:
              </label>
              <div className="space-y-2">
                {EXPERIENCE_SUGGESTIONS.map((item, idx) => (
                  <div
                    key={idx}
                    onClick={() => setGeneratedResult(item.bullet)}
                    className="p-3 rounded-xl border border-surface-border hover:border-primary hover:bg-primary/5 transition-all cursor-pointer group bg-surface-container-lowest"
                  >
                    <div className="flex items-center justify-between text-xs font-bold text-on-surface group-hover:text-primary mb-1">
                      <span>{item.role}</span>
                      <span className="text-[10px] text-primary flex items-center gap-0.5">
                        Usar frase <span className="material-symbols-outlined text-[12px]">arrow_forward</span>
                      </span>
                    </div>
                    <p className="text-[11px] text-on-surface-variant leading-relaxed">
                      {item.bullet}
                    </p>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* Mode Specific: Summary Presets */}
          {mode === 'summary' && (
            <div>
              <label className="block text-xs font-bold text-on-surface mb-2">
                Modelos Rápidos por Área de Atuação:
              </label>
              <div className="space-y-2">
                {AI_SUMMARY_SUGGESTIONS.map((item, idx) => (
                  <div
                    key={idx}
                    onClick={() => setGeneratedResult(item.text)}
                    className="p-3 rounded-xl border border-surface-border hover:border-primary hover:bg-primary/5 transition-all cursor-pointer group bg-surface-container-lowest"
                  >
                    <div className="flex items-center justify-between text-xs font-bold text-on-surface group-hover:text-primary mb-1">
                      <span>{item.role}</span>
                      <span className="text-[10px] text-primary flex items-center gap-0.5">
                        Selecionar <span className="material-symbols-outlined text-[12px]">arrow_forward</span>
                      </span>
                    </div>
                    <p className="text-[11px] text-on-surface-variant line-clamp-2">
                      {item.text}
                    </p>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* Mode Specific: Skills Categories */}
          {mode === 'skills' && (
            <div className="space-y-3">
              <label className="block text-xs font-bold text-on-surface">
                Pacotes de Competências em Alta no Mercado:
              </label>
              {SKILL_CATEGORIES.map((cat, cIdx) => (
                <div key={cIdx} className="p-3 bg-surface-container-low rounded-xl border border-surface-border/70 space-y-1.5">
                  <span className="text-[11px] font-bold text-on-surface-variant uppercase">
                    {cat.name}
                  </span>
                  <div className="flex flex-wrap gap-1.5">
                    {cat.skills.map((sk) => {
                      const isSelected = selectedSkills.includes(sk);
                      return (
                        <button
                          key={sk}
                          type="button"
                          onClick={() => toggleSkillSelection(sk)}
                          className={`text-xs px-2.5 py-1 rounded-lg font-medium transition-all flex items-center gap-1 ${
                            isSelected
                              ? 'bg-primary text-white shadow-2xs font-bold'
                              : 'bg-white text-slate-700 hover:bg-primary/10 hover:text-primary border border-surface-border'
                          }`}
                        >
                          <span>{sk}</span>
                          <span className="material-symbols-outlined text-[14px]">
                            {isSelected ? 'check' : 'add'}
                          </span>
                        </button>
                      );
                    })}
                  </div>
                </div>
              ))}
            </div>
          )}

          {/* Custom Instruction / Prompt Input */}
          <div>
            <label className="block text-xs font-bold text-on-surface mb-1">
              Personalizar ou Pedir Outra Frase:
            </label>
            <div className="flex gap-2">
              <input
                type="text"
                placeholder={
                  mode === 'skills'
                    ? 'ex: Vendas a retalho, petróleo e gás...'
                    : 'ex: Enfatizar liderança e redução de custos...'
                }
                value={customPrompt}
                onChange={(e) => setCustomPrompt(e.target.value)}
                className="flex-1 bg-surface-container-low border-none rounded-xl p-2.5 text-xs outline-none focus:ring-2 focus:ring-primary/20"
              />
              <button
                type="button"
                onClick={handleGenerateFromCustom}
                disabled={isGenerating || !customPrompt.trim()}
                className="bg-primary text-white px-4 py-2 rounded-xl text-xs font-bold hover:bg-primary/90 disabled:opacity-50 transition-all flex items-center gap-1"
              >
                <span className="material-symbols-outlined text-[16px]">spark</span>
                Gerar
              </button>
            </div>
          </div>

          {/* Generated Result Box */}
          {generatedResult && mode !== 'skills' && (
            <div className="p-4 bg-emerald-50 border border-emerald-200 rounded-xl space-y-2 animate-in fade-in duration-150">
              <div className="flex items-center justify-between">
                <span className="text-xs font-bold text-emerald-800 flex items-center gap-1">
                  <span className="material-symbols-outlined text-[16px]">check_circle</span>
                  Texto Otimizado Pronto:
                </span>
                <span className="text-[10px] text-emerald-700 font-semibold">Qualidade Verificada</span>
              </div>
              <p className="text-xs text-slate-800 leading-relaxed font-medium">
                {generatedResult}
              </p>
            </div>
          )}
        </div>

        {/* Modal Footer */}
        <div className="flex gap-3 pt-4 border-t border-surface-border">
          <button
            type="button"
            onClick={onClose}
            className="flex-1 px-4 py-2.5 rounded-xl border border-surface-border text-on-surface-variant font-semibold text-xs hover:bg-surface-container-low transition-colors"
          >
            Cancelar
          </button>
          <button
            type="button"
            disabled={mode === 'skills' ? selectedSkills.length === 0 : !generatedResult}
            onClick={() => {
              if (mode === 'skills' && onApplySkills) {
                onApplySkills(selectedSkills);
                onClose();
              } else if (generatedResult) {
                onApply(generatedResult);
                onClose();
              }
            }}
            className="flex-1 px-4 py-2.5 rounded-xl bg-primary text-white font-bold text-xs hover:bg-primary/95 disabled:opacity-50 shadow-md transition-all flex items-center justify-center gap-1.5"
          >
            <span className="material-symbols-outlined text-[16px]">done_all</span>
            {mode === 'skills'
              ? `Adicionar (${selectedSkills.length}) Competências`
              : 'Aplicar no Formulário'}
          </button>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { AppUser, ResumeData } from '../../types';
import { maskPhone, maskEmail, recordDeletionRequest, recordAuditLog } from '../../utils/security';
import { isStandalone, promptPWAInstall } from '../../utils/pwaManager';
import { PWAInstallModal } from '../common/PWAInstallModal';

interface AccountModalProps {
  isOpen?: boolean;
  user?: AppUser | null;
  resumeData?: ResumeData;
  onClose: () => void;
  onLogout?: () => void;
  onDeleteAccount?: () => void;
  onToast: (msg: string) => void;
  onOpenPrivacyPolicy?: () => void;
  onOpenTerms?: () => void;
  onNavigateMyCVs?: () => void;
  savedCVsCount?: number;
}

export const AccountModal: React.FC<AccountModalProps> = ({
  isOpen = true,
  user,
  resumeData,
  onClose,
  onLogout,
  onDeleteAccount,
  onToast,
  onOpenPrivacyPolicy,
  onOpenTerms,
  onNavigateMyCVs,
  savedCVsCount = 0,
}) => {
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);
  const [deleteReason, setDeleteReason] = useState('');
  const [isSubmittingDelete, setIsSubmittingDelete] = useState(false);
  const [deleteSuccess, setDeleteSuccess] = useState(false);
  const [showPWAInstallModal, setShowPWAInstallModal] = useState(false);

  if (!isOpen || !user) {
    return null;
  }

  const handleRequestDataDeletion = (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmittingDelete(true);

    try {
      // Record official deletion request under Lei 22/11
      const req = recordDeletionRequest({
        userId: user.id,
        userName: user.name,
        userEmail: user.email,
        userPhone: user.phone,
        reason: deleteReason.trim() || 'Solicitação do utilizador nos termos do Direito à Eliminação (Lei 22/11).',
      });

      // Record Audit Log
      recordAuditLog({
        accessedBy: user.email,
        actorRole: 'Titular dos Dados',
        targetUserId: user.id,
        targetUserName: user.name,
        accessType: 'pedido_eliminacao',
        details: `Submetido pedido de eliminação de dados (ID: ${req.id}). Motivo: "${deleteReason || 'Não especificado'}".`,
      });

      setDeleteSuccess(true);
      onToast('Pedido de eliminação de dados submetido com sucesso à equipa administrativa (Lei 22/11).');
    } catch (err) {
      onToast('Erro ao submeter pedido de eliminação. Tente novamente.');
    } finally {
      setIsSubmittingDelete(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-xs animate-in fade-in duration-200">
      <div className="bg-surface-container-lowest rounded-3xl max-w-xl w-full p-6 sm:p-8 shadow-2xl border border-surface-border animate-in zoom-in-95 duration-200 flex flex-col max-h-[90vh] overflow-y-auto">
        {/* Header */}
        <div className="flex items-center justify-between border-b border-surface-border pb-4">
          <div className="flex items-center gap-3">
            <div className="w-12 h-12 rounded-2xl bg-primary text-white flex items-center justify-center font-display font-bold text-lg shadow-xs">
              {user.initials || 'AO'}
            </div>
            <div>
              <h3 className="font-display text-lg font-bold text-on-surface">
                {user.name}
              </h3>
              <p className="text-xs text-on-surface-variant">
                Conta de Utilizador &bull; Registada em {user.registrationDate || '2026'}
              </p>
            </div>
          </div>
          <button
            onClick={onClose}
            className="text-on-surface-variant hover:text-on-surface p-2 rounded-xl hover:bg-surface-container-high transition-colors"
          >
            <span className="material-symbols-outlined">close</span>
          </button>
        </div>

        {/* Content */}
        {!showDeleteConfirm ? (
          <div className="py-5 space-y-5 text-xs sm:text-sm">
            {/* Quick Link to My CVs */}
            <div className="p-4 rounded-2xl bg-surface-container-high/60 border border-surface-border flex items-center justify-between gap-3">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 rounded-xl bg-primary/10 text-primary flex items-center justify-center">
                  <span className="material-symbols-outlined text-[22px]">folder_shared</span>
                </div>
                <div>
                  <h4 className="font-display font-bold text-xs sm:text-sm text-on-surface">
                    Meus Currículos Arquivados
                  </h4>
                  <p className="text-[11px] text-on-surface-variant">
                    {savedCVsCount} {savedCVsCount === 1 ? 'currículo guardado' : 'currículos guardados'} na sua conta
                  </p>
                </div>
              </div>
              <button
                type="button"
                onClick={() => {
                  onClose();
                  if (onNavigateMyCVs) onNavigateMyCVs();
                }}
                className="px-4 py-2 rounded-xl bg-primary hover:bg-primary/95 text-white text-xs font-bold font-display shadow-xs transition-all flex items-center gap-1 cursor-pointer"
              >
                <span>Ver Meus CVs</span>
                <span className="material-symbols-outlined text-[16px]">arrow_forward</span>
              </button>
            </div>

            {/* Account Details Card */}
            <div className="p-4 rounded-2xl bg-surface-container-low border border-surface-border space-y-2.5">
              <div className="flex items-center justify-between text-xs">
                <span className="text-on-surface-variant font-medium">E-mail:</span>
                <span className="font-mono font-bold text-on-surface">{user.email}</span>
              </div>
              <div className="flex items-center justify-between text-xs">
                <span className="text-on-surface-variant font-medium">Telemóvel:</span>
                <span className="font-mono font-bold text-on-surface">{user.phone}</span>
              </div>
              <div className="flex items-center justify-between text-xs">
                <span className="text-on-surface-variant font-medium">Estado da Conta:</span>
                <span className="inline-flex items-center gap-1 px-2.5 py-0.5 rounded-full text-[11px] font-bold bg-emerald-100 text-emerald-800">
                  <span className="w-1.5 h-1.5 rounded-full bg-emerald-600"></span>
                  {user.status || 'Ativo'}
                </span>
              </div>
            </div>

            {/* Data Protection & Encryption Badge (Lei 22/11) */}
            <div className="p-4 rounded-2xl bg-primary/5 border border-primary/20 space-y-2 text-xs">
              <div className="flex items-center gap-2 text-primary font-bold">
                <span className="material-symbols-outlined text-[18px]">lock</span>
                Proteção de Dados Pessoais (Lei n.º 22/11)
              </div>
              <p className="text-slate-600 leading-relaxed text-[11px] sm:text-xs">
                Todos os seus dados sensíveis (fotografia tipo passe, histórico profissional e comprovativos de pagamento) são armazenados sob <strong>encriptação em repouso</strong> e transmitidos via protocolo seguro <strong>HTTPS</strong>.
              </p>
              <div className="flex items-center gap-4 text-[11px] font-semibold text-primary pt-1">
                <button
                  type="button"
                  onClick={() => {
                    onClose();
                    if (onOpenPrivacyPolicy) onOpenPrivacyPolicy();
                  }}
                  className="hover:underline flex items-center gap-1"
                >
                  <span className="material-symbols-outlined text-[14px]">policy</span>
                  Política de Privacidade
                </button>
                <button
                  type="button"
                  onClick={() => {
                    onClose();
                    if (onOpenTerms) onOpenTerms();
                  }}
                  className="hover:underline flex items-center gap-1"
                >
                  <span className="material-symbols-outlined text-[14px]">gavel</span>
                  Termos de Uso
                </button>
              </div>
            </div>

            {/* Retention Policy Note */}
            <div className="p-4 rounded-2xl bg-amber-50 border border-amber-200 text-amber-900 text-xs space-y-1">
              <div className="flex items-center gap-1.5 font-bold">
                <span className="material-symbols-outlined text-[16px] text-amber-700">schedule</span>
                Política de Retenção de Dados
              </div>
              <p className="text-[11px] leading-relaxed text-amber-800">
                Os dados do seu CV são mantidos enquanto mantiver a conta ativa para lhe permitir editar e descarregar o ficheiro. Pode solicitar a qualquer momento a eliminação integral dos seus dados.
              </p>
            </div>

            {/* PWA App Installation Option */}
            {!isStandalone() && (
              <div className="p-3.5 rounded-2xl bg-blue-500/10 border border-blue-500/30 flex items-center justify-between gap-3">
                <div className="flex items-center gap-2.5">
                  <div className="w-8 h-8 rounded-xl bg-blue-600 text-white flex items-center justify-center shrink-0">
                    <span className="material-symbols-outlined text-[18px]">install_mobile</span>
                  </div>
                  <div>
                    <h5 className="font-bold text-xs text-blue-950">
                      Instalar no Ecrã Principal
                    </h5>
                    <p className="text-[11px] text-blue-800/80">
                      Acesso rápido como aplicação nativa PWA
                    </p>
                  </div>
                </div>
                <button
                  type="button"
                  onClick={async () => {
                    const res = await promptPWAInstall();
                    if (res === 'manual_guide' || res === 'dismissed') {
                      setShowPWAInstallModal(true);
                    }
                  }}
                  className="px-3 py-1.5 rounded-xl bg-blue-600 hover:bg-blue-700 text-white font-bold text-xs shadow-xs transition-all cursor-pointer"
                >
                  Instalar
                </button>
              </div>
            )}

            {/* Right to be Forgotten / Delete Action */}
            <div className="pt-2 border-t border-surface-border flex flex-col gap-2">
              <button
                type="button"
                onClick={() => setShowDeleteConfirm(true)}
                className="w-full py-3 px-4 rounded-xl border border-error/30 bg-error-container/20 text-error hover:bg-error-container/40 text-xs font-bold transition-all flex items-center justify-center gap-2 cursor-pointer"
              >
                <span className="material-symbols-outlined text-[18px]">delete_forever</span>
                Solicitar Eliminação dos Meus Dados (Lei 22/11)
              </button>
            </div>
          </div>
        ) : (
          <div className="py-5 space-y-4">
            {!deleteSuccess ? (
              <form onSubmit={handleRequestDataDeletion} className="space-y-4">
                <div className="p-4 rounded-2xl bg-error-container/20 border border-error/30 text-xs space-y-2">
                  <div className="flex items-center gap-2 text-error font-bold text-sm">
                    <span className="material-symbols-outlined text-[20px]">warning</span>
                    Direito à Eliminação de Dados Pessoais
                  </div>
                  <p className="text-slate-700 leading-relaxed">
                    Em conformidade com a <strong>Lei n.º 22/11 da República de Angola</strong>, tem o direito de solicitar a eliminação definitiva de todos os seus dados pessoais, fotografias e histórico de currículos armazenados na plataforma.
                  </p>
                  <p className="text-slate-600 font-medium">
                    O seu pedido será encaminhado para processamento imediato pelo <strong>DPO da CV IA Angola (Chinua Ndembo, Lda)</strong>. Linha de apoio: <strong>957 427 090</strong>.
                  </p>
                </div>

                <div>
                  <label className="block text-xs font-semibold text-on-surface mb-1">
                    Motivo da solicitação (opcional):
                  </label>
                  <textarea
                    rows={3}
                    placeholder="ex: Já não necessito do serviço / Desejo expurgar os meus dados de contacto."
                    value={deleteReason}
                    onChange={(e) => setDeleteReason(e.target.value)}
                    className="w-full bg-surface-container-low border border-surface-border rounded-xl p-3 text-xs outline-none focus:border-primary focus:ring-2 focus:ring-primary/20"
                  />
                </div>

                <div className="flex items-center justify-end gap-3 pt-2">
                  <button
                    type="button"
                    onClick={() => setShowDeleteConfirm(false)}
                    className="px-4 py-2.5 rounded-xl border border-surface-border text-on-surface hover:bg-surface-container text-xs font-bold transition-all"
                  >
                    Cancelar
                  </button>
                  <button
                    type="submit"
                    disabled={isSubmittingDelete}
                    className="px-5 py-2.5 rounded-xl bg-error text-white text-xs font-bold hover:bg-error/90 transition-all shadow-xs flex items-center gap-1.5 cursor-pointer disabled:opacity-50"
                  >
                    {isSubmittingDelete ? (
                      <span>A submeter...</span>
                    ) : (
                      <>
                        <span className="material-symbols-outlined text-[16px]">send</span>
                        Confirmar e Enviar Pedido
                      </>
                    )}
                  </button>
                </div>
              </form>
            ) : (
              <div className="p-6 rounded-2xl bg-emerald-50 border border-emerald-200 text-center space-y-3">
                <div className="w-12 h-12 rounded-full bg-emerald-100 text-emerald-700 flex items-center justify-center mx-auto">
                  <span className="material-symbols-outlined text-[24px]">check</span>
                </div>
                <h4 className="font-bold text-base text-emerald-900">
                  Pedido Registado com Sucesso!
                </h4>
                <p className="text-xs text-emerald-800 leading-relaxed max-w-md mx-auto">
                  O seu pedido de eliminação foi registado nos termos da Lei 22/11 e encaminhado com carimbo de auditoria para <strong>admin.prospekta@gmail.com</strong>.
                </p>
                <button
                  type="button"
                  onClick={onClose}
                  className="px-6 py-2.5 rounded-xl bg-emerald-700 text-white text-xs font-bold hover:bg-emerald-800 transition-all"
                >
                  Fechar
                </button>
              </div>
            )}
          </div>
        )}

        {/* Footer */}
        <div className="pt-4 border-t border-surface-border flex items-center justify-between">
          <button
            type="button"
            onClick={onLogout}
            className="text-xs font-bold text-error hover:underline flex items-center gap-1 cursor-pointer"
          >
            <span className="material-symbols-outlined text-[16px]">logout</span>
            Terminar Sessão
          </button>
          <button
            type="button"
            onClick={onClose}
            className="px-5 py-2 rounded-xl bg-surface-container text-on-surface hover:bg-surface-container-high text-xs font-bold transition-all cursor-pointer"
          >
            Fechar
          </button>
        </div>
      </div>

      {/* PWA Install Guide Modal */}
      <PWAInstallModal
        isOpen={showPWAInstallModal}
        onClose={() => setShowPWAInstallModal(false)}
      />
    </div>
  );
};

