                </div>
                <div className="text-left text-xs">
                  <div className="font-extrabold text-emerald-900 flex items-center gap-1">
                    <span>Apoio WhatsApp:</span>
                    <span className="font-mono text-emerald-700 font-bold">957 427 090</span>
