                      </span>
                    ) : isPending ? (
                      <span className="inline-flex items-center gap-1 px-2.5 py-1 rounded-full text-[10px] font-bold bg-blue-100 text-blue-900 flex-shrink-0">
                        <span className="material-symbols-outlined text-[12px]">hourglass_top</span>
                        Em Validação
                      </span>
