                  {/* Secondary Actions (Edit, Duplicate for Family, Delete) */}
                  <div className="flex items-center justify-between pt-1 text-xs">
                    <div className="flex items-center gap-1">
                      {isFullyPaid && (
                        <button
                          type="button"
