import React, { useState, useRef, useEffect } from 'react';

interface PassportPhotoModalProps {
  initialImage?: string;
  onApplyPhoto: (photoDataUrl: string) => void;
  onClose: () => void;
}

type BackgroundColorOption = 'white' | 'light-blue' | 'neutral-gray' | 'original';

export const PassportPhotoModal: React.FC<PassportPhotoModalProps> = ({
  initialImage,
  onApplyPhoto,
  onClose,
}) => {
  const [imageSrc, setImageSrc] = useState<string | null>(initialImage || null);
  const [zoom, setZoom] = useState<number>(1.2);
  const [panX, setPanX] = useState<number>(0);
  const [panY, setPanY] = useState<number>(0);
  const [brightness, setBrightness] = useState<number>(105);
  const [contrast, setContrast] = useState<number>(105);
  const [bgChoice, setBgChoice] = useState<BackgroundColorOption>('white');
  const [isProcessing, setIsProcessing] = useState(false);

  const canvasRef = useRef<HTMLCanvasElement>(null);
  const imgRef = useRef<HTMLImageElement | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Load image object when imageSrc changes
  useEffect(() => {
    if (!imageSrc) return;
    const img = new Image();
    img.crossOrigin = 'anonymous';
    img.onload = () => {
      imgRef.current = img;
      renderCanvas();
    };
    img.src = imageSrc;
  }, [imageSrc]);

  // Re-render canvas on adjustments
  useEffect(() => {
    renderCanvas();
  }, [zoom, panX, panY, brightness, contrast, bgChoice]);

  const renderCanvas = () => {
    const canvas = canvasRef.current;
    const img = imgRef.current;
    if (!canvas || !img) return;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const width = 360;
    const height = 480; // 3:4 passport aspect ratio (standard 35mm x 45mm proportion)
    canvas.width = width;
    canvas.height = height;

    // 1. Draw Background
    if (bgChoice === 'white') {
      ctx.fillStyle = '#FFFFFF';
      ctx.fillRect(0, 0, width, height);
    } else if (bgChoice === 'light-blue') {
      ctx.fillStyle = '#E0F2FE';
      ctx.fillRect(0, 0, width, height);
    } else if (bgChoice === 'neutral-gray') {
      ctx.fillStyle = '#F1F5F9';
      ctx.fillRect(0, 0, width, height);
    } else {
      ctx.fillStyle = '#FFFFFF';
      ctx.fillRect(0, 0, width, height);
    }

    // 2. Setup Filters (Brightness & Contrast)
    ctx.filter = `brightness(${brightness}%) contrast(${contrast}%)`;

    // 3. Calculate Draw Dimensions with Zoom and Pan
    const imgAspect = img.width / img.height;
    const canvasAspect = width / height;

    let drawWidth: number;
    let drawHeight: number;

    if (imgAspect > canvasAspect) {
      drawHeight = height * zoom;
      drawWidth = drawHeight * imgAspect;
    } else {
      drawWidth = width * zoom;
      drawHeight = drawWidth / imgAspect;
    }

    const offsetX = (width - drawWidth) / 2 + panX;
    const offsetY = (height - drawHeight) / 2 + panY;

    // Draw the image onto canvas
    ctx.drawImage(img, offsetX, offsetY, drawWidth, drawHeight);

    // Reset filter
    ctx.filter = 'none';
  };

  // Handle local file selection
  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setImageSrc(reader.result as string);
        setZoom(1.2);
        setPanX(0);
        setPanY(0);
      };
      reader.readAsDataURL(file);
    }
  };

  // Auto-center & optimize preset
  const handleAutoFitPassport = () => {
    setZoom(1.35);
    setPanX(0);
    setPanY(15);
    setBrightness(108);
    setContrast(105);
    setBgChoice('white');
  };

  // Export finished passport photo
  const handleSaveAndApply = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    setIsProcessing(true);
    setTimeout(() => {
      const dataUrl = canvas.toDataURL('image/jpeg', 0.95);
      onApplyPhoto(dataUrl);
      setIsProcessing(false);
      onClose();
    }, 400);
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-xs">
      <div className="bg-surface-container-lowest rounded-2xl max-w-2xl w-full p-6 shadow-2xl border border-surface-border animate-in fade-in zoom-in-95 duration-200 flex flex-col max-h-[92vh]">
        {/* Modal Header */}
        <div className="flex items-center justify-between border-b border-surface-border pb-4">
          <div className="flex items-center gap-2.5">
            <div className="w-9 h-9 rounded-xl bg-primary/10 flex items-center justify-center text-primary">
              <span className="material-symbols-outlined text-[22px]">badge</span>
            </div>
            <div>
              <h3 className="font-display text-base font-bold text-on-surface">
                Editor de Foto Tipo Passe (Padrão Corporativo)
              </h3>
              <p className="text-xs text-on-surface-variant">
                Enquadramento 3:4 vertical com guia facial e fundo neutro para CVs em Angola.
              </p>
            </div>
          </div>
          <button
            onClick={onClose}
            className="text-on-surface-variant hover:text-on-surface p-1.5 rounded-lg hover:bg-surface-container-high transition-colors"
          >
            <span className="material-symbols-outlined">close</span>
          </button>
        </div>

        {/* Modal Body */}
        <div className="flex-1 overflow-y-auto py-4 grid grid-cols-1 md:grid-cols-12 gap-6 items-start">
          {/* Left: Canvas Preview & Passport Guide */}
          <div className="md:col-span-5 flex flex-col items-center">
            <div className="relative w-[210px] h-[280px] rounded-2xl overflow-hidden shadow-md border-2 border-primary/40 bg-slate-100 flex items-center justify-center">
              {imageSrc ? (
                <>
                  <canvas
                    ref={canvasRef}
                    className="w-full h-full object-cover"
                  />
                  {/* Passport Biometric Overlay Guide */}
                  <div className="absolute inset-0 pointer-events-none border border-dashed border-primary/30 rounded-xl m-2 flex flex-col items-center justify-between p-2">
                    {/* Head Guide Oval */}
                    <div className="w-24 h-32 rounded-[50%] border border-primary/40 mt-3 relative">
                      {/* Eye Line Guide */}
                      <div className="absolute top-[45%] left-0 right-0 border-t border-dotted border-primary/50"></div>
                      {/* Center Axis */}
                      <div className="absolute top-0 bottom-0 left-1/2 border-l border-dotted border-primary/50"></div>
                    </div>
                    <span className="text-[9px] bg-slate-900/70 text-white font-mono px-2 py-0.5 rounded-full">
                      Guia de Enquadramento
                    </span>
                  </div>
                </>
              ) : (
                <div className="text-center p-4 text-on-surface-variant space-y-2">
                  <span className="material-symbols-outlined text-[40px] text-primary">add_a_photo</span>
                  <p className="text-xs font-semibold">Nenhuma foto carregada</p>
                  <p className="text-[10px]">Carregue uma selfie ou foto de rosto para começar.</p>
                </div>
              )}
            </div>

            {/* Upload or Change button */}
            <input
              type="file"
              ref={fileInputRef}
              accept="image/*"
              onChange={handleFileChange}
              className="hidden"
            />
            <button
              type="button"
              onClick={() => fileInputRef.current?.click()}
              className="mt-3 w-[210px] py-2 bg-surface-container-high hover:bg-surface-container-highest text-on-surface text-xs font-bold rounded-xl transition-all flex items-center justify-center gap-1.5 border border-surface-border"
            >
              <span className="material-symbols-outlined text-[16px]">upload_file</span>
              {imageSrc ? 'Carregar Outra Foto' : 'Selecionar Foto'}
            </button>

            {imageSrc && (
              <button
                type="button"
                onClick={handleAutoFitPassport}
                className="mt-2 w-[210px] py-1.5 bg-primary/10 hover:bg-primary/20 text-primary text-[11px] font-bold rounded-xl transition-all flex items-center justify-center gap-1"
              >
                <span className="material-symbols-outlined text-[14px]">auto_fix_high</span>
                Auto-Centrar & Otimizar
              </button>
            )}
          </div>

          {/* Right: Controls & Adjustments */}
          <div className="md:col-span-7 space-y-4">
            {/* Background Selector */}
            <div className="p-3 bg-surface-container-low rounded-xl border border-surface-border">
              <label className="block text-xs font-bold text-on-surface mb-2 flex items-center justify-between">
                <span>Fundo Neutro Tipo Passe:</span>
                <span className="text-[10px] text-primary font-normal">Recomendado para recrutamento</span>
              </label>
              <div className="grid grid-cols-3 gap-2">
                <button
                  type="button"
                  onClick={() => setBgChoice('white')}
                  className={`p-2 rounded-xl text-xs font-bold border transition-all flex items-center gap-2 ${
                    bgChoice === 'white'
                      ? 'border-primary bg-primary/10 text-primary ring-1 ring-primary'
                      : 'border-surface-border bg-white text-slate-700 hover:bg-slate-50'
                  }`}
                >
                  <span className="w-3.5 h-3.5 rounded-full bg-white border border-slate-300 shadow-2xs"></span>
                  Branco Puro
                </button>

                <button
                  type="button"
                  onClick={() => setBgChoice('light-blue')}
                  className={`p-2 rounded-xl text-xs font-bold border transition-all flex items-center gap-2 ${
                    bgChoice === 'light-blue'
                      ? 'border-primary bg-primary/10 text-primary ring-1 ring-primary'
                      : 'border-surface-border bg-white text-slate-700 hover:bg-slate-50'
                  }`}
                >
                  <span className="w-3.5 h-3.5 rounded-full bg-sky-100 border border-sky-300 shadow-2xs"></span>
                  Azul Claro
                </button>

                <button
                  type="button"
                  onClick={() => setBgChoice('neutral-gray')}
                  className={`p-2 rounded-xl text-xs font-bold border transition-all flex items-center gap-2 ${
                    bgChoice === 'neutral-gray'
                      ? 'border-primary bg-primary/10 text-primary ring-1 ring-primary'
                      : 'border-surface-border bg-white text-slate-700 hover:bg-slate-50'
                  }`}
                >
                  <span className="w-3.5 h-3.5 rounded-full bg-slate-200 border border-slate-300 shadow-2xs"></span>
                  Cinza Estúdio
                </button>
              </div>
            </div>

            {/* Zoom & Positioning Sliders */}
            <div className="p-3 bg-surface-container-low rounded-xl border border-surface-border space-y-3">
              <h4 className="text-xs font-bold text-on-surface">Ajuste de Posição e Zoom</h4>

              <div>
                <div className="flex justify-between text-xs mb-1">
                  <span className="text-on-surface-variant font-medium">Zoom / Escala</span>
                  <span className="font-mono text-primary font-bold">{zoom.toFixed(1)}x</span>
                </div>
                <input
                  type="range"
                  min="0.8"
                  max="2.5"
                  step="0.05"
                  value={zoom}
                  onChange={(e) => setZoom(parseFloat(e.target.value))}
                  className="w-full accent-primary h-1.5 bg-surface-container rounded-lg cursor-pointer"
                />
              </div>

              <div className="grid grid-cols-2 gap-3">
                <div>
                  <div className="flex justify-between text-[11px] mb-1">
                    <span className="text-on-surface-variant">Posição Vertical (Y)</span>
                    <span className="font-mono text-on-surface">{panY}px</span>
                  </div>
                  <input
                    type="range"
                    min="-100"
                    max="100"
                    step="2"
                    value={panY}
                    onChange={(e) => setPanY(parseInt(e.target.value, 10))}
                    className="w-full accent-primary h-1.5 bg-surface-container rounded-lg cursor-pointer"
                  />
                </div>

                <div>
                  <div className="flex justify-between text-[11px] mb-1">
                    <span className="text-on-surface-variant">Posição Horizontal (X)</span>
                    <span className="font-mono text-on-surface">{panX}px</span>
                  </div>
                  <input
                    type="range"
                    min="-100"
                    max="100"
                    step="2"
                    value={panX}
                    onChange={(e) => setPanX(parseInt(e.target.value, 10))}
                    className="w-full accent-primary h-1.5 bg-surface-container rounded-lg cursor-pointer"
                  />
                </div>
              </div>
            </div>

            {/* Brightness & Contrast */}
            <div className="p-3 bg-surface-container-low rounded-xl border border-surface-border space-y-3">
              <h4 className="text-xs font-bold text-on-surface">Iluminação e Nitidez Facial</h4>

              <div className="grid grid-cols-2 gap-3">
                <div>
                  <div className="flex justify-between text-[11px] mb-1">
                    <span className="text-on-surface-variant">Luminosidade</span>
                    <span className="font-mono text-on-surface">{brightness}%</span>
                  </div>
                  <input
                    type="range"
                    min="80"
                    max="140"
                    step="1"
                    value={brightness}
                    onChange={(e) => setBrightness(parseInt(e.target.value, 10))}
                    className="w-full accent-primary h-1.5 bg-surface-container rounded-lg cursor-pointer"
                  />
                </div>

                <div>
                  <div className="flex justify-between text-[11px] mb-1">
                    <span className="text-on-surface-variant">Contraste</span>
                    <span className="font-mono text-on-surface">{contrast}%</span>
                  </div>
                  <input
                    type="range"
                    min="80"
                    max="140"
                    step="1"
                    value={contrast}
                    onChange={(e) => setContrast(parseInt(e.target.value, 10))}
                    className="w-full accent-primary h-1.5 bg-surface-container rounded-lg cursor-pointer"
                  />
                </div>
              </div>
            </div>
          </div>
        </div>

        {/* Modal Footer */}
        <div className="flex gap-3 pt-4 border-t border-surface-border">
          <button
            type="button"
            onClick={onClose}
            className="flex-1 px-4 py-2.5 rounded-xl border border-surface-border text-on-surface-variant font-semibold text-xs hover:bg-surface-container-low transition-colors"
          >
            Cancelar
          </button>
          <button
            type="button"
            disabled={!imageSrc || isProcessing}
            onClick={handleSaveAndApply}
            className="flex-1 px-4 py-2.5 rounded-xl bg-primary text-white font-bold text-xs hover:bg-primary/95 disabled:opacity-50 shadow-md transition-all flex items-center justify-center gap-1.5"
          >
            <span className="material-symbols-outlined text-[16px]">check_circle</span>
            {isProcessing ? 'A Processar...' : 'Aplicar Foto no Currículo'}
          </button>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import confetti from 'canvas-confetti';
import { sendPaymentDiscordNotification } from '../../utils/discordNotification';

export interface SubmittedPaymentData {
  method: 'Multicaixa' | 'Transferência';
  txId: string;
  userPhone?: string;
  referenceCode?: string;
  senderLast4?: string;
  senderName?: string;
  receiptFileName?: string;
  receiptFileSize?: string;
  receiptMimeType?: string;
  receiptUploadedAt?: string;
  receiptUrl?: string;
}

interface PaymentModalProps {
  amount: number;
  userName?: string;
  userEmail?: string;
  templateName?: string;
  onPaymentSuccess?: (method: 'Multicaixa' | 'Transferência', txId: string) => void;
  onPaymentSubmitted: (data: SubmittedPaymentData) => void;
  onClose: () => void;
}

export const PaymentModal: React.FC<PaymentModalProps> = ({
  amount,
  userName = 'Cliente Luanda',
  userEmail = 'cliente@email.ao',
  templateName = 'Lumina Modern',
  onPaymentSuccess,
  onPaymentSubmitted,
  onClose,
}) => {
  const [method, setMethod] = useState<'Multicaixa' | 'Transferência'>('Multicaixa');

  // Multicaixa Xpress Form State
  const [userPhone, setUserPhone] = useState('');
  const [mcxTxCode, setMcxTxCode] = useState('');
  const [mcxLast4, setMcxLast4] = useState('');

  // Transferência BAI Form State
  const [baiReference, setBaiReference] = useState('');
  const [baiSenderName, setBaiSenderName] = useState('');
  const [baiSenderLast4, setBaiSenderLast4] = useState('');
  const [receiptFileName, setReceiptFileName] = useState<string | null>(null);
  const [receiptFileSize, setReceiptFileSize] = useState<string | null>(null);
  const [receiptMimeType, setReceiptMimeType] = useState<string | null>(null);
  const [receiptUploadedAt, setReceiptUploadedAt] = useState<string | null>(null);
  const [receiptDataUrl, setReceiptDataUrl] = useState<string | null>(null);
  const [fileError, setFileError] = useState<string | null>(null);

  const [copiedField, setCopiedField] = useState<string | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [paymentSuccess, setPaymentSuccess] = useState(false);
  const [submittedTxId, setSubmittedTxId] = useState('');
  const [discordNotified, setDiscordNotified] = useState(false);

  const copyToClipboard = (text: string, fieldId: string) => {
    navigator.clipboard.writeText(text);
    setCopiedField(fieldId);
    setTimeout(() => setCopiedField(null), 2000);
  };

  const formatFileSize = (bytes: number): string => {
    if (bytes < 1024) return `${bytes} B`;
    if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
    return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    setFileError(null);
    const file = e.target.files?.[0];
    if (!file) return;

    // Strict validation: must be image (jpg, jpeg, png, webp)
    const validImageTypes = ['image/jpeg', 'image/png', 'image/webp', 'image/jpg'];
    if (!validImageTypes.includes(file.type.toLowerCase())) {
      setFileError('Formato inválido! Por favor, anexe uma imagem válida nos formatos JPG ou PNG.');
      setReceiptFileName(null);
      setReceiptDataUrl(null);
      setReceiptFileSize(null);
      setReceiptMimeType(null);
      return;
    }

    // Size limit: 10MB
    if (file.size > 10 * 1024 * 1024) {
      setFileError('O ficheiro excede o tamanho máximo de 10 MB.');
      return;
    }

    setReceiptFileName(file.name);
    setReceiptFileSize(formatFileSize(file.size));
    setReceiptMimeType(file.type);
    setReceiptUploadedAt(new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }));

    const reader = new FileReader();
    reader.onload = (event) => {
      if (event.target?.result) {
        setReceiptDataUrl(event.target.result as string);
      }
    };
    reader.readAsDataURL(file);
  };

  const handleProcessPayment = async (e: React.FormEvent) => {
    e.preventDefault();

    // Validate mandatory last 4 digits for cross-verification
    const effectiveLast4 =
      method === 'Multicaixa'
        ? mcxLast4.trim() || (userPhone.trim().replace(/\D/g, '').slice(-4))
        : baiSenderLast4.trim();

    if (!effectiveLast4 || effectiveLast4.length < 3) {
      alert('Por favor, insira os últimos 4 dígitos do número de telefone ou conta bancária usada para verificação.');
      return;
    }

    setIsProcessing(true);

    const generatedId =
      method === 'Multicaixa'
        ? `MCX-${Math.floor(1000 + Math.random() * 9000)}${String.fromCharCode(
            65 + Math.floor(Math.random() * 26)
          )}`
        : `BAI-${Math.floor(10000 + Math.random() * 90000)}`;

    setSubmittedTxId(generatedId);

    const refCode = method === 'Multicaixa' ? mcxTxCode.trim() || generatedId : baiReference.trim() || generatedId;
    const finalPhone = userPhone.trim() ? (userPhone.startsWith('+244') ? userPhone : `+244 ${userPhone}`) : undefined;

    // Send Discord Webhook notification via server API
    try {
      const discordRes = await sendPaymentDiscordNotification({
        userName,
        userEmail,
        userPhone: finalPhone,
        amount,
        method,
        referenceCode: refCode,
        senderLast4: effectiveLast4,
        senderName: method === 'Transferência' ? baiSenderName.trim() : undefined,
        receiptFileName: receiptFileName || undefined,
        receiptFileSize: receiptFileSize || undefined,
        receiptMimeType: receiptMimeType || undefined,
        receiptUrl: receiptDataUrl || undefined,
        txId: generatedId,
        templateName,
      });
      if (discordRes.success) {
        setDiscordNotified(true);
      }
    } catch (err) {
      console.warn('Erro ao disparar webhook Discord:', err);
    }

    setIsProcessing(false);
    setPaymentSuccess(true);

    // Trigger subtle confetti
    confetti({
      particleCount: 60,
      spread: 60,
      origin: { y: 0.6 },
    });

    const paymentData: SubmittedPaymentData = {
      method,
      txId: generatedId,
      userPhone: finalPhone,
      referenceCode: refCode,
      senderLast4: effectiveLast4,
      senderName: method === 'Transferência' ? baiSenderName.trim() : undefined,
      receiptFileName: receiptFileName || undefined,
      receiptFileSize: receiptFileSize || undefined,
      receiptMimeType: receiptMimeType || undefined,
      receiptUploadedAt: receiptUploadedAt || undefined,
      receiptUrl: receiptDataUrl || undefined,
    };

    setTimeout(() => {
      onPaymentSubmitted(paymentData);
      if (onPaymentSuccess) {
        onPaymentSuccess(method, generatedId);
      }
    }, 1800);
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-xs">
      <div className="bg-surface-container-lowest rounded-2xl max-w-lg w-full p-6 shadow-2xl border border-surface-border animate-in fade-in zoom-in-95 duration-200 max-h-[92vh] overflow-y-auto">
        {/* Header */}
        <div className="flex items-center justify-between border-b border-surface-border pb-4">
          <div className="flex items-center gap-2.5">
            <div className="w-9 h-9 rounded-xl bg-primary/10 flex items-center justify-center text-primary">
              <span className="material-symbols-outlined text-[20px]">payments</span>
            </div>
            <div>
              <h3 className="font-display text-base font-bold text-on-surface">
                Submeter Comprovativo de Pagamento
              </h3>
              <p className="text-xs text-on-surface-variant">
                {amount.toLocaleString()} Kz &bull; Multicaixa Xpress ou Transferência BAI
              </p>
            </div>
          </div>
          <button
            onClick={onClose}
            className="text-on-surface-variant hover:text-on-surface p-1.5 rounded-lg hover:bg-surface-container-high transition-colors"
          >
            <span className="material-symbols-outlined text-[20px]">close</span>
          </button>
        </div>

        {paymentSuccess ? (
          <div className="py-8 text-center space-y-4 animate-in fade-in zoom-in-95 duration-200">
            <div className="w-16 h-16 rounded-full bg-amber-50 text-amber-600 flex items-center justify-center mx-auto shadow-inner ring-8 ring-amber-50">
              <span className="material-symbols-outlined text-[36px]">hourglass_top</span>
            </div>
            <div className="space-y-1">
              <h4 className="font-display text-lg font-bold text-on-surface">
                Comprovativo Submetido com Sucesso!
              </h4>
              <p className="text-xs text-on-surface-variant max-w-sm mx-auto leading-relaxed">
                O seu pedido está agora no estado <strong>"Pagamento em análise"</strong>.
                O administrador foi notificado automaticamente para validação.
              </p>
            </div>

            <div className="p-3.5 bg-surface-container-low rounded-xl text-xs space-y-1.5 border border-surface-border inline-block text-left w-full max-w-sm">
              <div className="flex justify-between">
                <span className="text-on-surface-variant">ID da Transação:</span>
                <span className="font-mono font-bold text-primary">{submittedTxId}</span>
              </div>
              <div className="flex justify-between">
                <span className="text-on-surface-variant">Método:</span>
                <span className="font-bold text-on-surface">
                  {method === 'Multicaixa' ? 'Multicaixa Xpress' : 'Transferência BAI'}
                </span>
              </div>
              <div className="flex justify-between">
                <span className="text-on-surface-variant">Valor:</span>
                <span className="font-bold text-slate-900 font-display">{amount.toLocaleString()} Kz</span>
              </div>
              <div className="flex justify-between items-center pt-1 border-t border-surface-border/60">
                <span className="text-on-surface-variant">Notificação Discord:</span>
                <span className="text-[10.5px] font-bold text-emerald-700 bg-emerald-100 px-2 py-0.5 rounded-full flex items-center gap-1">
                  <span className="material-symbols-outlined text-[13px]">check</span>
                  Enviada ao Admin
                </span>
              </div>
            </div>

            <div className="bg-amber-50 border border-amber-200 text-amber-900 text-xs p-3 rounded-xl max-w-sm mx-auto flex items-start gap-2 text-left">
              <span className="material-symbols-outlined text-[16px] text-amber-700 shrink-0 mt-0.5">info</span>
              <span>
                Assim que o administrador confirmar o recebimento no painel, o seu currículo será desbloqueado automaticamente para download em PDF.
              </span>
            </div>
          </div>
        ) : (
          <form onSubmit={handleProcessPayment} className="py-4 space-y-4">
            {/* Price Banner */}
            <div className="p-4 bg-primary/5 rounded-2xl border border-primary/20 flex items-center justify-between">
              <div>
                <span className="text-xs text-on-surface-variant font-medium">Valor do Desbloqueio</span>
                <p className="text-2xl font-black font-display text-primary">
                  {amount.toLocaleString()} <span className="text-sm font-semibold">Kz</span>
                </p>
              </div>
              <div className="text-right">
