          </svg>
          <span className="hidden sm:inline font-mono">957 427 090</span>
          <span className="sm:hidden text-[11px]">Ajuda</span>
        </a>

        {currentUser ? (
          <div className="flex items-center gap-2">
            {/* Direct Meus CVs Button */}
            <button
              id="header-my-cvs-btn"
