                  src={currentUser.avatarUrl}
                  alt={currentUser.name}
                  className="w-6 h-6 rounded-lg object-cover ring-1 ring-primary/20 shrink-0"
                />
              ) : (
                <div className="w-6 h-6 rounded-lg bg-primary text-white text-[10px] font-extrabold flex items-center justify-center shrink-0">
                  {currentUser.initials || (currentUser.name ? currentUser.name.slice(0, 2).toUpperCase() : 'CV')}
                </div>
              )}

              <span className="text-xs font-bold truncate max-w-[90px] sm:max-w-[120px] hidden sm:inline">
                {currentUser.name.split(' ')[0]}
              </span>

              <span className="material-symbols-outlined text-[16px] text-on-surface-variant">
                manage_accounts
              </span>
            </button>

            {/* Quick Action: Criar CV if on home or my-cvs */}
            {currentView !== 'builder' && (
              <button
                id="header-create-cv-btn"
                onClick={() => setCurrentView('builder')}
                className="hidden md:flex items-center gap-1 px-3 py-1.5 bg-primary hover:bg-primary/90 text-white rounded-xl text-xs font-bold shadow-xs transition-all cursor-pointer"
              >
                <span className="material-symbols-outlined text-[16px]">add_circle</span>
                <span>Novo CV</span>
              </button>
            )}
          </div>
        ) : (
          <div className="flex items-center gap-2">
            <button
              id="header-login-btn"
              onClick={() => onOpenAuth('login')}
              className="px-3.5 py-1.5 rounded-xl text-xs font-bold text-on-surface hover:bg-surface-container transition-all cursor-pointer"
            >
              Entrar
            </button>

            <button
              id="header-register-btn"
              onClick={() => onOpenAuth('register_input')}
              className="flex items-center gap-1 px-3.5 py-1.5 bg-primary hover:bg-primary/90 text-white rounded-xl text-xs font-bold shadow-xs transition-all cursor-pointer"
            >
              <span className="material-symbols-outlined text-[15px]">person_add</span>
              <span>Cadastrar</span>
            </button>
          </div>
        )}
      </div>

      {/* PWA Installation & Step by Step Guide Modal */}
      <PWAInstallModal
        isOpen={showPWAInstallModal}
        onClose={() => setShowPWAInstallModal(false)}
      />
    </header>
  );
};

